    ('402f38a8-f484-49eb-99bb-d508093abbd3'::uuid, 'period_start', NULL, '-4000', 'fields-wd1-2026-09-26d-s007-rollback:402f38a8-f484-49eb-99bb-d508093abbd3:period_start', 'rollback of fields-wd1-2026-09-26d-s007: period_start ''-4000'' restored on Nine Maidens Stone Row', '[{"source": "WD1 decision (counted, round 1, wd1-r1-b0007)", "decision": "clear", "status": "MISSING", "reasoning": "Wikipedia calls the St Columb Major row ''late neolithic'', the Megalithic Portal ''Neolithic and Bronze Age'' and other pages ''early bronze-age'', but none of the readable sources gives this row a year, century or millennium; the only numeric range found (2500BC-1000BC on a blog) is a generic one for stone rows, which are ''notoriously hard to date''. With no two independent dated sources, and nothing supporting the stored 4000 BC, the field is cleared.", "value_page": null}]'::jsonb),
