    ('40ce67f7-1961-49cd-beff-33c03f702a17'::uuid, 'period_start', '-5000', '-2000', 'fields-wd1-2026-09-26d-s007-rollback:40ce67f7-1961-49cd-beff-33c03f702a17:period_start', 'rollback of fields-wd1-2026-09-26d-s007: period_start ''-2000'' restored on Mycenae', '[{"source": "https://en.wikipedia.org/wiki/Mycenae", "url": "https://en.wikipedia.org/wiki/Mycenae", "quote": "it was continuously occupied from the Early Neolithic (EN, c. 5000–c. 4000 BC)", "outcome": "found"}, {"source": "https://ancientgreecewanderings.com/visiting-mycenae-archaeological-site/", "url": "https://ancientgreecewanderings.com/visiting-mycenae-archaeological-site/", "quote": "The first human activity in Mycenae is traced back to the 7th millennium BC.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0200)", "decision": "replace", "status": "MISSING", "reasoning": "Wikipedia says the site was continuously occupied from the Early Neolithic (c. 5000-4000 BC), and Ancient Greece Wanderings traces the first human activity at Mycenae to the 7th millennium BC; the start lies before 4500 BC, not in 3000 - 1500 BC.", "value_page": null}]'::jsonb),
