    ('41070db5-8f7c-4d69-8652-cc2d4bfb8bf4'::uuid, 'site_type', 'Temple', 'Temple complex', 'fields-wd1-2026-09-26d-s007-rollback:41070db5-8f7c-4d69-8652-cc2d4bfb8bf4:site_type', 'rollback of fields-wd1-2026-09-26d-s007: site_type ''Temple complex'' restored on Qasr Sagha Temple', '[{"source": "https://madainproject.com/qasr_el_sagha_temple", "url": "https://madainproject.com/qasr_el_sagha_temple", "quote": "The so-called Qasr el-Sagha is an ancient Egyptian Middle Kingdom temple situated on the northern escarpment of the Faiyum Depression in Egypt", "outcome": "found"}, {"source": "https://egyptfuntours.com/qasr-el-sagha/", "url": "https://egyptfuntours.com/qasr-el-sagha/", "quote": "Key Highlights: Qasr El Sagha at a Glance What It Is: An unfinished, 4,000-year-old temple from Egypt’s Middle Kingdom.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0048)", "decision": "replace", "status": "MISSING", "reasoning": "Madain Project calls it a Middle Kingdom temple and Egypt Fun Tours an unfinished 4,000-year-old temple: a single temple.", "value_page": null}]'::jsonb),
