    ('418f6d87-0fc3-4eb6-a310-e45a1fb43a3d'::uuid, 'source_url', 'https://turkisharchaeonews.net/site/asclepieion-pergamon', 'http://www.my-favourite-planet.de/english/middle-east/turkey/pergamon/pergamon-photos-01-035.html', 'fields-wd1-2026-09-26d-s007-rollback:418f6d87-0fc3-4eb6-a310-e45a1fb43a3d:source_url', 'rollback of fields-wd1-2026-09-26d-s007: source_url ''http://www.my-favourite-planet.de/english/middle-east/turkey/pergamon/pergamon-photos-01-035.html'' restored on Asclepieion of Pergamon', '[{"source": "https://turkisharchaeonews.net/site/asclepieion-pergamon", "url": "https://turkisharchaeonews.net/site/asclepieion-pergamon", "quote": "Contact Asclepieion of Pergamon Submitted by Iza on Tue, 01/02/2024 - 18:50.", "outcome": "found"}, {"source": "https://travelshelper.com/turkey/places-in-turkey/asclepion-of-pergamon/", "url": "https://travelshelper.com/turkey/places-in-turkey/asclepion-of-pergamon/", "quote": "Asclepion of Pergamon in Bergama, Turkey", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0392)", "decision": "replace", "status": "MISSING", "reasoning": "Turkish Archaeological News''s page is about the Asclepieion of Pergamon, which Travels Helper names too; the stored photo page does not name the site.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('4190c8a6-db2f-442b-8125-f2df42cf51a0'::uuid, 'site_type', 'Residence/villa/farmhouse', 'Megalithic structures', 'fields-wd1-2026-09-26d-s007-rollback:4190c8a6-db2f-442b-8125-f2df42cf51a0:site_type', 'rollback of fields-wd1-2026-09-26d-s007: site_type ''Megalithic structures'' restored on Villa of Theseus', '[{"source": "https://www.realjourneytravels.com/places/villa-of-theseus/", "url": "https://www.realjourneytravels.com/places/villa-of-theseus/", "quote": "The Villa of Theseus, located in the Paphos Archaeological Park, is a testament to Roman opulence and artistry.", "outcome": "found"}, {"source": "https://hebrewexplorer.com/archaeology/paphos-house-of-theseus-governors-villa/", "url": "https://hebrewexplorer.com/archaeology/paphos-house-of-theseus-governors-villa/", "quote": "The largest Roman residence known on Cyprus, about 120 by 80 m, with a central court, private baths, marble statuary and mosaic floors", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0040)", "decision": "replace", "status": "MISSING", "reasoning": "Real Journey Travels describes the Villa of Theseus as a Roman villa and Hebrew Explorer as the largest Roman residence known on Cyprus; Megalithic structures is wrong.", "value_page": null}]'::jsonb),
    ('41bb2c5e-4eb3-4bdf-8d1e-6ea497c44b26'::uuid, 'site_type', 'Fort', 'Fortress/citadel', 'fields-wd1-2026-09-26d-s007-rollback:41bb2c5e-4eb3-4bdf-8d1e-6ea497c44b26:site_type', 'rollback of fields-wd1-2026-09-26d-s007: site_type ''Fortress/citadel'' restored on Havránok', '[{"source": "https://en.wikipedia.org/wiki/Havr%C3%A1nok", "url": "https://en.wikipedia.org/wiki/Havr%C3%A1nok", "quote": "The archaeologists unearthed a prehistoric Celtic hill fort and a medieval wooden castle in the 1960s, during the construction of the Liptovská Mara dam.", "outcome": "found"}, {"source": "https://www.liptovskemuzeum.sk/havranok-o-archeoskanzene-havranok", "url": "https://www.liptovskemuzeum.sk/havranok-o-archeoskanzene-havranok", "quote": "V období mladej doby železnej bolo na kopci vybudované hradisko, ktoré slúžilo nielen ako útočisko v čase ohrozenia", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0017)", "decision": "replace", "status": "MISSING", "reasoning": "Wikipedia describes Havránok above Liptovská Mara as a prehistoric Celtic hill fort, and the Liptov Museum, which runs the open-air site, says a hradisko (hillfort) was built on the hill in the Late Iron Age as a refuge; no source calls it a fortress or citadel, so the hillfort is best held by Fort.", "value_page": null}]'::jsonb),
